import assert from "node:assert/strict";
import { execFile } from "node:child_process";
import { access, mkdtemp, readFile, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, relative } from "node:path";
import { promisify } from "node:util";
import test from "node:test";

import { createPublicationPreview } from "./publication.mjs";
import { createReportStore } from "./storage.mjs";

const TEST_MODEL = "test-model";
const execFileAsync = promisify(execFile);

test("reports persist under a durable issue identity, not a panel ID", async () => {
  const workspace = await mkdtemp(join(tmpdir(), "aspnetcore-triage-"));
  const store = createReportStore(workspace);
  const report = {
    schemaVersion: "1.0.0",
    repository: "dotnet/aspnetcore",
    issueNumber: 123,
    issueUrl: "https://github.com/dotnet/aspnetcore/issues/123",
    area: "area-blazor",
    createdAt: "2026-09-06T19:00:00Z",
    model: TEST_MODEL,
    messageId: "message-1",
    skill: ".github/skills/investigate-issue/SKILL.md",
    skillDigest: "a".repeat(64),
    content: "advisory report",
    stopPath: false,
  };
  await store.write(report);

  assert.deepEqual(await store.read(123), report);
  const filePath = join(
    workspace,
    "files",
    "aspnetcore-issue-triage",
    "reports",
    "dotnet-aspnetcore-issue-123.json",
  );
  assert.match(await readFile(filePath, "utf8"), /"issueNumber": 123/);
  assert.doesNotMatch(filePath, /instance|panel/);
});

test("stop-path status survives storage and human draft replacement", async () => {
  const workspace = await mkdtemp(join(tmpdir(), "aspnetcore-triage-"));
  const store = createReportStore(workspace);
  const report = {
    schemaVersion: "1.0.0",
    repository: "dotnet/aspnetcore",
    issueNumber: 124,
    issueUrl: "https://github.com/dotnet/aspnetcore/issues/124",
    area: "area-blazor",
    createdAt: "2026-09-06T19:00:00Z",
    model: TEST_MODEL,
    messageId: "message-2",
    skill: ".github/skills/investigate-issue/SKILL.md",
    skillDigest: "b".repeat(64),
    content: "**Classification:** Do not publish\n**Preliminary assessment:** Security process required.",
  };
  await store.write(report);
  const seeded = await store.seedWorkspace(await store.read(124));
  const saved = await store.saveDraft(
    124,
    "**Classification:** Research\n\nHuman correction.\n\n> Generated by GitHub Copilot; AI-assisted and non-binding.",
    seeded.draft.revision,
    "human",
  );

  assert.equal(saved.stopPath, true);
  assert.throws(
    () => createPublicationPreview({
      issue: {
        repository: "dotnet/aspnetcore",
        number: 124,
        url: "https://github.com/dotnet/aspnetcore/issues/124",
        state: "open",
        public: true,
        isPullRequest: false,
        updatedAt: "issue-revision",
      },
      account: { login: "human", id: 1 },
      report: {
        content: saved.draft.content,
        stopPath: saved.stopPath,
      },
      draftRevision: saved.draft.revision,
    }),
    (error) => error.code === "publication_stop_path",
  );
});

test("cross-process draft saves use an exclusive artifact lock", async () => {
  const workspace = await mkdtemp(join(tmpdir(), "aspnetcore-triage-"));
  const store = createReportStore(workspace);
  await store.write({
    schemaVersion: "1.0.0",
    repository: "dotnet/aspnetcore",
    issueNumber: 125,
    issueUrl: "https://github.com/dotnet/aspnetcore/issues/125",
    area: "area-blazor",
    createdAt: "2026-09-06T19:00:00Z",
    model: TEST_MODEL,
    messageId: "message-3",
    skill: ".github/skills/investigate-issue/SKILL.md",
    skillDigest: "c".repeat(64),
    content: "Original report",
    stopPath: false,
  });
  await store.seedWorkspace(await store.read(125));
  const storageUrl = new URL("./storage.mjs", import.meta.url).href;
  const script = `
    import { createReportStore } from ${JSON.stringify(storageUrl)};
    const store = createReportStore(process.env.TRIAGE_WORKSPACE);
    try {
      const saved = await store.saveDraft(125, process.env.TRIAGE_CONTENT, 1, "human");
      console.log(JSON.stringify({ ok: true, revision: saved.draft.revision }));
    } catch (error) {
      console.log(JSON.stringify({ ok: false, code: error.code }));
      process.exitCode = 2;
    }
  `;
  const results = await Promise.allSettled([
    execFileAsync(process.execPath, ["--input-type=module", "-e", script], {
      env: { ...process.env, TRIAGE_WORKSPACE: workspace, TRIAGE_CONTENT: "first" },
    }),
    execFileAsync(process.execPath, ["--input-type=module", "-e", script], {
      env: { ...process.env, TRIAGE_WORKSPACE: workspace, TRIAGE_CONTENT: "second" },
    }),
  ]);
  const outputs = results.map((result) => JSON.parse(
    result.status === "fulfilled" ? result.value.stdout : result.reason.stdout,
  ));
  assert.equal(outputs.filter((result) => result.ok).length, 1);
  assert.equal(outputs.filter((result) => !result.ok).length, 1);
  assert.equal((await store.readWorkspace(125)).draft.revision, 2);
});

test("the selected area persists at session scope for provider rehydration", async () => {
  const workspace = await mkdtemp(join(tmpdir(), "aspnetcore-triage-"));
  const first = createReportStore(workspace);
  await first.writeArea("area-perf");

  const rehydrated = createReportStore(workspace);
  assert.equal(await rehydrated.readArea(), "area-perf");
});

test("the session-local model setting uses the fixed artifact root outside the checkout", async () => {
  const workspace = await mkdtemp(join(tmpdir(), "aspnetcore-triage-"));
  const repositoryRoot = await mkdtemp(join(tmpdir(), "aspnetcore-repo-"));
  const store = createReportStore(workspace, repositoryRoot);

  assert.equal(await store.readModel(), null);
  await store.writeModel(TEST_MODEL);

  assert.equal(await store.readModel(), TEST_MODEL);
  const settingsPath = join(
    workspace,
    "files",
    "aspnetcore-issue-triage",
    "model-settings.json",
  );
  assert.match(await readFile(settingsPath, "utf8"), /"model": "test-model"/);
  assert.ok(relative(repositoryRoot, settingsPath).startsWith(".."));

  await writeFile(settingsPath, "{", "utf8");
  await assert.rejects(
    store.readModel(),
    (error) => error.code === "model_settings_invalid",
  );
});

test("artifact storage rejects a workspace inside the repository checkout", () => {
  assert.throws(
    () => createReportStore("/repo/.copilot/artifacts", "/repo"),
    (error) => error.code === "artifact_storage_invalid",
  );
});

test("cancelled durable writes never replace session artifacts", async () => {
  const workspace = await mkdtemp(join(tmpdir(), "aspnetcore-triage-"));
  const store = createReportStore(workspace);
  await assert.rejects(
    store.writeArea("area-blazor", () => false),
    (error) => error.code === "artifact_write_cancelled",
  );
  assert.equal(await store.readArea(), null);

  const preferencesPath = join(
    workspace,
    "files",
    "aspnetcore-issue-triage",
    "preferences.json",
  );
  await assert.rejects(access(preferencesPath), (error) => error.code === "ENOENT");
});

test("editable workspaces seed once, preserve the original report, and enforce revisions", async () => {
  const workspace = await mkdtemp(join(tmpdir(), "aspnetcore-triage-"));
  const store = createReportStore(workspace);
  const report = {
    schemaVersion: "1.0.0",
    repository: "dotnet/aspnetcore",
    issueNumber: 456,
    issueUrl: "https://github.com/dotnet/aspnetcore/issues/456",
    area: "area-blazor",
    createdAt: "2026-09-06T19:00:00Z",
    model: TEST_MODEL,
    messageId: "message-2",
    skill: ".github/skills/investigate-issue/SKILL.md",
    skillDigest: "b".repeat(64),
    content: "original report",
  };
  const first = await store.seedWorkspace(report);
  assert.equal(first.originalReport.content, report.content);
  assert.match(first.draft.content, /original report/);
  assert.match(first.draft.content, /AI-assisted and non-binding/);
  assert.equal((await store.seedWorkspace({ ...report, content: "replacement" })).draft.content, first.draft.content);

  const edited = await store.saveDraft(456, "human draft", first.draft.revision, "human");
  assert.equal(edited.draft.revision, first.draft.revision + 1);
  assert.equal(edited.originalReport.content, report.content);
  await assert.rejects(
    store.saveDraft(456, "stale draft", first.draft.revision, "human"),
    (error) => error.code === "stale_revision",
  );
  const undone = await store.undoDraft(456, edited.draft.revision);
  assert.equal(undone.draft.content, first.draft.content);
  assert.equal((await store.readWorkspace(456)).draft.revision, undone.draft.revision);
});
